// The links you want QR codes for — replace with your own list.
// name = output filename, url = content the QR code encodes.
const links = [
  { name: "homepage", url: "https://bulkqrgenerator.net/" },
  { name: "guest-wifi", url: "WIFI:T:WPA;S:GuestNetwork;P:super-secret;;" },
  { name: "call-support", url: "tel:+1234567890" },
];

const API = "https://bulkqrgenerator.net/api/v1/qr";

return links.map((link) => ({
  json: {
    ...link,
    qrUrl: `${API}?text=${encodeURIComponent(link.url)}&format=png&size=512&margin=2`,
  },
}));
